// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {PoCGame} from "../src/PoCGame.sol";

contract InvMutTest is Test {
    PoCGame c;
    address owner;

    function setUp() public {
        address __invmut_eoa = address(uint160(0xE0A));
        vm.deal(__invmut_eoa, 100 ether);
        vm.startPrank(__invmut_eoa, __invmut_eoa);
        c = new PoCGame(address(this), 0);
        vm.stopPrank();
        owner = __invmut_eoa;
    }

    function testFuzz_property(address actor) public {
        vm.assume(uint160(actor) != 0);
        vm.deal(actor, 100 ether);
        // owner opens the contract (owner is an EOA, tx.origin must match)
        vm.startPrank(owner, owner);
        c.OpenToThePublic();
        vm.stopPrank();
        // a real person wagers the configured bet limit (betLimit = 0)
        uint256 limit = c.currentBetLimit();
        vm.deal(actor, limit);
        bool ok;
        vm.startPrank(actor, actor);
        try c.wager{value: limit}() {
            ok = true;
        } catch {
            ok = false;
        }
        vm.stopPrank();
        assertTrue(ok);
    }
}
